mapper.select:
SELECT msg.id, msg.room_id, msg.user_id, msg.content, msg.msg_type, msg.created_at,
       COALESCE(NULLIF(TRIM(u.nickname), ''), u.username) AS nickname,
       u.avatar_url AS avatar_url
FROM room_messages msg
LEFT JOIN users u ON msg.user_id = u.id
WHERE msg.room_id = #{roomId}
  AND msg.id > #{afterId}
ORDER BY msg.id ASC
LIMIT #{limit}
